class Solution {
public:
    int maxTotalFruits(vector<vector<int>>& fruits, int startPos, int k) {
        int n = fruits.size(), res = 0, j = 0, sum = 0;
        for (int i = 0; i < n; ++i) {
            sum += fruits[i][1];
            while (j <= i && min(abs(fruits[i][0] - startPos), abs(fruits[j][0] - startPos)) + fruits[i][0] - fruits[j][0] > k)
                sum -= fruits[j++][1];
            res = max(res, sum);
        }
        return res;
    }
};
